package clientsgen

import (
	"bytes"
	"fmt"
	"go/format"
	"sort"
	"text/template"
)

// generatedHeader is the machine-readable marker every emitted file starts
// with. The exact wording ("Code generated ... DO NOT EDIT.") is the
// convention golang.org/x/tools and most Go tooling key drift/lint
// exemptions off of.
const generatedHeader = "// Code generated by tools/gen/clients from " + DefaultManifestPath + ". DO NOT EDIT."

// docFileTemplate is the package documentation file. It is the one file
// that also carries a real package doc comment (the blank line between the
// generated-header line and the doc-comment block keeps the header from
// becoming part of the doc comment itself, matching how protoc-gen-go's own
// output separates the two).
const docFileTemplate = generatedHeader + `

// Package clients holds the TOOL-007 generated transport-agnostic
// capability clients for IntentService and RegistryService: one interface
// per service, a native gRPC backend and a connect-go backend, both
// decoding a failure into the identical *envelope.Error (see
// DecodeGRPCError, DecodeConnectError). PROTO-006's parity suite exercises
// both backends against the shared internal/transport/transporttest fixture
// and requires them to agree on everything: domain result, typed error,
// evidence identifiers, deadline propagation, and the refusal of a
// caller-selected trusted-context header.
//
// Regenerate with ` + "`go run ./tools/gen/clients/cmd/generateclients`" + `.
package clients
`

// supportFileTemplate is the shared, service-independent runtime: call
// options and the two backends' identical error decoding. It does not vary
// with the manifest, so it renders as a literal rather than through
// text/template, but it is still emitted by [Render] so the whole package
// is one generation output.
const supportFileTemplate = generatedHeader + `

package clients

import (
	"context"
	"errors"

	"connectrpc.com/connect"
	"google.golang.org/grpc/codes"
	"google.golang.org/grpc/metadata"

	commonv1 "github.com/monstercameron/hcm-next/gen/go/hcmnext/common/v1"
	"github.com/monstercameron/hcm-next/internal/transport"
	"github.com/monstercameron/hcm-next/internal/transport/envelope"
)

// CallOptions carries the per-call metadata a [CallOption] sets.
type CallOptions struct {
	Headers map[string]string
}

// CallOption configures one outbound call. Both backends project the same
// key onto their own header/metadata shape identically: the same key
// becomes the same gRPC metadata key and the same HTTP header, because
// gRPC-Go and connect-go both canonicalize keys to lower case.
type CallOption func(*CallOptions)

// WithHeader sets one outbound header/metadata key. A repeated key keeps
// its last value.
func WithHeader(key, value string) CallOption {
	return func(o *CallOptions) {
		if o.Headers == nil {
			o.Headers = make(map[string]string, 1)
		}
		o.Headers[key] = value
	}
}

// WithAuthorization sets the request's credential, e.g. "Bearer <token>".
func WithAuthorization(credential string) CallOption {
	return WithHeader(transport.AuthorizationMetadataKey, credential)
}

// WithRequestID sets the caller's own correlation identifier.
func WithRequestID(id string) CallOption {
	return WithHeader(transport.RequestIDMetadataKey, id)
}

// newCallOptions applies opts in order.
func newCallOptions(opts []CallOption) *CallOptions {
	o := &CallOptions{}
	for _, opt := range opts {
		opt(o)
	}
	return o
}

// applyGRPCOptions projects opts onto ctx as outgoing gRPC metadata.
func applyGRPCOptions(ctx context.Context, opts []CallOption) context.Context {
	o := newCallOptions(opts)
	if len(o.Headers) == 0 {
		return ctx
	}
	pairs := make([]string, 0, len(o.Headers)*2)
	for k, v := range o.Headers {
		pairs = append(pairs, k, v)
	}
	return metadata.AppendToOutgoingContext(ctx, pairs...)
}

// applyConnectOptions projects opts onto req's outbound HTTP headers.
func applyConnectOptions[T any](req *connect.Request[T], opts []CallOption) {
	o := newCallOptions(opts)
	for k, v := range o.Headers {
		req.Header().Set(k, v)
	}
}

// DecodeGRPCError extracts the owned *envelope.Error from a native gRPC
// client failure. err is returned unchanged when it carries no gRPC status.
func DecodeGRPCError(err error) error {
	if err == nil {
		return nil
	}
	if owned, ok := envelope.FromGRPC(err); ok {
		return owned
	}
	return err
}

// DecodeConnectError extracts the owned *envelope.Error from a connect-go
// client failure, projecting the same hcmnext.common.v1.ErrorDetail
// [envelope.FromGRPC] does, so a caller sees an identical *envelope.Error
// regardless of which backend produced it. err is returned unchanged when
// it is not a *connect.Error.
func DecodeConnectError(err error) error {
	if err == nil {
		return nil
	}
	var connectErr *connect.Error
	if !errors.As(err, &connectErr) {
		return err
	}
	var detail *commonv1.ErrorDetail
	for _, d := range connectErr.Details() {
		value, valueErr := d.Value()
		if valueErr != nil {
			continue
		}
		if ed, ok := value.(*commonv1.ErrorDetail); ok {
			detail = ed
			break
		}
	}
	return envelope.FromDetail(envelope.CodeFromGRPC(codes.Code(connectErr.Code())), connectErr.Message(), detail)
}
`

// serviceFileTemplateSrc renders one service's interface, procedure
// constants and two backends.
const serviceFileTemplateSrc = generatedHeader + `

package clients

import (
	"context"

	"connectrpc.com/connect"
	"google.golang.org/grpc"

{{- range .Imports}}
	{{.Alias}} "{{.ImportPath}}"
{{- end}}
)

// Procedure paths for {{.FullName}}, identical to the gRPC method's
// FullMethod and to connect.Spec.Procedure.
const (
{{- range .Methods}}
	Procedure{{.Name}} = "{{.Procedure}}"
{{- end}}
)

// Procedures{{.ShortName}} returns every procedure path {{.ClientName}}
// publishes, in manifest order.
func Procedures{{.ShortName}}() []string {
	return []string{
{{- range .Methods}}
		Procedure{{.Name}},
{{- end}}
	}
}

// {{.ClientName}} is the transport-agnostic capability client for
// {{.FullName}}. Both [New{{.ClientName}}GRPC] and [New{{.ClientName}}Connect]
// decode a failure into the identical *envelope.Error (DecodeGRPCError,
// DecodeConnectError), so calling code does not depend on which backend it
// was built with.
type {{.ClientName}} interface {
{{- range .Methods}}
	// {{.Name}} calls {{$.FullName}}.{{.Name}}.{{if eq .Disposition "REFUSED_P1A"}} The method exists
	// on the wire for P1B forward compatibility; every P1A invocation is
	// refused (disposition REFUSED_P1A), identically on both backends.{{end}}
	{{.Name}}(ctx context.Context, req *{{.Request.Qualified}}, opts ...CallOption) (*{{.Response.Qualified}}, error)
{{- end}}
}

// {{.FieldPrefix}}GRPCClient is the native gRPC backend for {{.ClientName}}.
type {{.FieldPrefix}}GRPCClient struct {
	client {{.GoType.Alias}}.{{.ShortName}}Client
}

// New{{.ClientName}}GRPC builds a {{.ClientName}} that calls {{.FullName}}
// over native gRPC on cc.
func New{{.ClientName}}GRPC(cc grpc.ClientConnInterface) {{.ClientName}} {
	return &{{.FieldPrefix}}GRPCClient{client: {{.GoType.Alias}}.New{{.ShortName}}Client(cc)}
}
{{range .Methods}}
// {{.Name}} calls {{$.FullName}}.{{.Name}} over native gRPC.
func (c *{{$.FieldPrefix}}GRPCClient) {{.Name}}(ctx context.Context, req *{{.Request.Qualified}}, opts ...CallOption) (*{{.Response.Qualified}}, error) {
	res, err := c.client.{{.Name}}(applyGRPCOptions(ctx, opts), req)
	if err != nil {
		return nil, DecodeGRPCError(err)
	}
	return res, nil
}
{{end}}
// {{.FieldPrefix}}ConnectClient is the connect-go backend for {{.ClientName}}.
type {{.FieldPrefix}}ConnectClient struct {
{{- range .Methods}}
	{{lowerFirst .Name}} *connect.Client[{{.Request.Qualified}}, {{.Response.Qualified}}]
{{- end}}
}

// New{{.ClientName}}Connect builds a {{.ClientName}} that calls the
// {{.FullName}} procedures published at baseURL over connect-go.
func New{{.ClientName}}Connect(httpClient connect.HTTPClient, baseURL string, opts ...connect.ClientOption) {{.ClientName}} {
	return &{{.FieldPrefix}}ConnectClient{
{{- range .Methods}}
		{{lowerFirst .Name}}: connect.NewClient[{{.Request.Qualified}}, {{.Response.Qualified}}](httpClient, baseURL+Procedure{{.Name}}, opts...),
{{- end}}
	}
}
{{range .Methods}}
// {{.Name}} calls {{$.FullName}}.{{.Name}} over connect-go.
func (c *{{$.FieldPrefix}}ConnectClient) {{.Name}}(ctx context.Context, req *{{.Request.Qualified}}, opts ...CallOption) (*{{.Response.Qualified}}, error) {
	connectReq := connect.NewRequest(req)
	applyConnectOptions(connectReq, opts)
	res, err := c.{{lowerFirst .Name}}.CallUnary(ctx, connectReq)
	if err != nil {
		return nil, DecodeConnectError(err)
	}
	return res.Msg, nil
}
{{end}}
`

// aggregateFileTemplateSrc renders the cross-service Procedures() helper.
const aggregateFileTemplateSrc = generatedHeader + `

package clients

// Procedures returns every procedure path every generated client publishes,
// across every service.
func Procedures() []string {
	var out []string
{{- range .}}
	out = append(out, Procedures{{.ShortName}}()...)
{{- end}}
	return out
}
`

var serviceFileTemplate = template.Must(template.New("service").Funcs(template.FuncMap{
	"lowerFirst": lowerFirst,
}).Parse(serviceFileTemplateSrc))

var aggregateFileTemplate = template.Must(template.New("aggregate").Parse(aggregateFileTemplateSrc))

// Render computes every file [BuildModel]'s services produce, gofmt'd, keyed
// by the filename it belongs at under internal/transport/clients. It is
// pure: given the same manifest and the same linked descriptors, it always
// returns the same bytes, which is what makes generation something a test
// can assert is deterministic rather than merely believed to be.
func Render(manifestPath string) (map[string][]byte, error) {
	services, err := BuildModel(manifestPath)
	if err != nil {
		return nil, err
	}

	files := map[string][]byte{
		"doc.go":     []byte(docFileTemplate),
		"support.go": []byte(supportFileTemplate),
	}

	for _, svc := range services {
		var buf bytes.Buffer
		if err := serviceFileTemplate.Execute(&buf, svc); err != nil {
			return nil, fmt.Errorf("clientsgen: rendering %s: %w", svc.FullName, err)
		}
		files[serviceFileName(svc)] = buf.Bytes()
	}

	var aggBuf bytes.Buffer
	if err := aggregateFileTemplate.Execute(&aggBuf, services); err != nil {
		return nil, fmt.Errorf("clientsgen: rendering procedures.go: %w", err)
	}
	files["procedures.go"] = aggBuf.Bytes()

	for name, src := range files {
		formatted, err := format.Source(src)
		if err != nil {
			return nil, fmt.Errorf("clientsgen: formatting %s: %w\n%s", name, err, src)
		}
		files[name] = formatted
	}
	return files, nil
}

// serviceFileName is the committed filename for svc's generated file, e.g.
// "intent_client.go" for IntentService.
func serviceFileName(svc serviceModel) string {
	return toSnake(svc.FieldPrefix) + "_client.go"
}

// toSnake lower-cases a camelCase identifier into snake_case. FieldPrefix
// values are short single-word stems today ("intent", "registry"), so this
// only needs to handle inserting an underscore before an interior capital.
func toSnake(s string) string {
	var out []byte
	for i := 0; i < len(s); i++ {
		c := s[i]
		if c >= 'A' && c <= 'Z' {
			if i > 0 {
				out = append(out, '_')
			}
			c = c - 'A' + 'a'
		}
		out = append(out, c)
	}
	return string(out)
}

// sortedFileNames returns names sorted, for deterministic write order.
func sortedFileNames(files map[string][]byte) []string {
	names := make([]string, 0, len(files))
	for name := range files {
		names = append(names, name)
	}
	sort.Strings(names)
	return names
}
